nta.declaration:
const int NUM_CIRCLES = 3;
const int NUM_SQUARES = 3;
const int NUM_ENEMIES = NUM_CIRCLES + NUM_SQUARES;

const int TIMEOUT = 100;
const int MAIN_TOWER_HEALTH = 10;

const int CIRCLE_SPEED = 1;
const int CIRCLE_HEALTH = 10;
const int CIRCLE_DAMAGE = 2;

const int SQUARE_SPEED = 3;
const int SQUARE_HEALTH = 20;
const int SQUARE_DAMAGE = 4;

const int PATH_LENGTH = 23;
typedef struct {
  int x;
  int y;
} Coord;

int spawn_time[NUM_ENEMIES] = {0, 2, 4, 1, 3, 5};
int lives = MAIN_TOWER_HEALTH;
int global_clock = 0;
bool game_over = false;
bool timeout_reached = false;

const Coord path[PATH_LENGTH] = {
  {0,0}, {1,0}, {2,0}, {3,0}, {4,0}, 
  {4,1}, {4,2}, {4,3}, {4,4}, {5,4},
  {6,4}, {7,4}, {8,4}, {8,5}, {8,6}, 
  {8,7}, {9,7}, {10,7}, {11,7}, {12,7}, 
  {13,7}, {14,7}, {15,4}
};

const Coord mainTower = {15, 4};

template.declaration:
/**
 * Enemy automaton.
 * Manages one enemy's spawning, movement, reaching goal, and game damage.
 */
clock clk;
int hp;    // Health of the enemy
int pos = 0; // Position on path
int speed; // Movement speed
int dmg;   // Damage dealt to the tower
bool active = false;

nta.system:
// ==========================
// System Declarations
// ==========================

clockTick = ClockTick();
GM = GameMonitor();

// Enemy instantiations
E0 = Enemy(0);
E1 = Enemy(1);
E2 = Enemy(2);
E3 = Enemy(3);
E4 = Enemy(4);
E5 = Enemy(5);

system clockTick, GM, E0, E1, E2, E3, E4, E5;
